// IANA zone, never by adding a fixed offset. That was the root cause of the old
// send-window bug, which was off by the UTC offset.

const DAYS = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

function localParts(date, tz) {
