const BAND_ALIASES = { under500k: 'under500k', '500k-2m': '500k-1m', '2m-5m': '1m-3m', '5m-10m': '3m-10m', '10mplus': 'over10m', '500k-1m': '500k-1m', '1m-3m': '1m-3m', '3m-10m': '3m-10m', over10m: 'over10m' };
